# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Dependency contract: hae/evaluation/artifacts.py
# Since this module is being implemented in parallel, we import it.
# If it's not available, we might need a fallback, but the prompt implies it exists.
try:
    from hae.evaluation.artifacts import (
        filter_bundle,
        partition_bundle,
        count_source_files,
        is_generated_path,
        is_malformed_path,
        sanitize_path
    )
except ImportError:
    # Fallback implementation if artifacts.py is not yet available or import fails
    # This ensures the harness can still run if the dependency is missing during dev
    EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
    EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

    def is_generated_path(path: str) -> bool:
        parts = path.replace('\\', '/').split('/')
        for part in parts[:-1]: # Check directories, not the filename itself usually, but spec says "lives inside"
            if part in EXCLUDED_DIR_SEGMENTS:
                return True
            if any(part.endswith(s) for s in EXCLUDED_DIR_SUFFIXES):
                return True
        return False

    def is_malformed_path(path: str) -> bool:
        if not path:
            return True
        if path != path.strip():
            return True
        if '*' in path or '`' in path:
            return True
        if path.startswith('-'):
            return True
        if path.endswith('.') or path.endswith('~'):
            return True
        return False

    def sanitize_path(path: str) -> str:
        path = path.strip()
        path = path.replace('*', '').replace('`', '')
        if path.startswith('-'):
            path = path[1:]
        if path.endswith('.') or path.endswith('~'):
            path = path[:-1]
        return path

    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return {k: v for k, v in bundle.items() if not is_generated_path(k) and not is_malformed_path(k)}

    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        authored = {}
        generated = {}
        malformed = {}
        for k, v in bundle.items():
            if is_generated_path(k):
                generated[k] = v
            elif is_malformed_path(k):
                malformed[k] = v
            else:
                authored[k] = v
        return authored, generated, malformed

    def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
        return sum(1 for k in bundle.keys() if any(k.endswith(s) for s in suffixes))


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed = [g for g in evaluated if g.passed]
        return len(passed) / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files} (Python: {self.python_files})")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append(f"Pass Rate: {self.pass_rate:.2%}")
        lines.append("-" * 40)
        for g in self.gates:
            status_icon = "✅" if g.passed else ("⏭️" if g.status == SKIPPED else "❌")
            lines.append(f"{status_icon} {g.name}: {g.status} ({g.method}) - {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "pass_rate": self.pass_rate,
            "gate_status": self.gate_status
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    import re
    # Match ```python ... ``` or ``` ... ```
    # We need to associate paths. Usually, the line before the block or inside the block indicates path.
    # Common pattern: ```python path/to/file.py
    # Or: ```python
    # followed by content.
    # The spec says "Recovers a path->content map".
    # If no path is provided, we might need to guess or skip.
    # Let's assume the standard format: ```python <path>

    blocks = {}
    # Regex to find fenced code blocks
    # Group 1: language (optional), Group 2: path (optional, on same line as fence), Group 3: content
    pattern = r"```(?:python|py)?\s*(.*?)\n(.*?)\n```"

    # This regex is tricky because content can contain newlines.
    # Let's use a simpler parser.

    lines = text.split('\n')
    in_block = False
    current_path = None
    current_content = []

    for line in lines:
        if line.startswith('```'):
            if in_block:
                # End of block
                if current_path:
                    blocks[current_path] = '\n'.join(current_content)
                in_block = False
                current_path = None
                current_content = []
            else:
                # Start of block
                in_block = True
                # Check if path is on the fence line
                # e.g. ```python src/main.py
                parts = line.split()
                if len(parts) > 1:
                    # Assume the second part is the path if it looks like a path
                    potential_path = parts[1]
                    if '.' in potential_path or '/' in potential_path:
                        current_path = potential_path
                    else:
                        current_path = None # Will need to infer or skip
                else:
                    current_path = None
        elif in_block:
            current_content.append(line)

    return blocks


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        if workspace is not None:
            # Assume workspace has a method to get files or is a dict
            if hasattr(workspace, 'get_files'):
                bundle = workspace.get_files()
            elif isinstance(workspace, dict):
                bundle = workspace
            else:
                # Try to treat it as a directory path if it's a string
                if isinstance(workspace, str) and os.path.isdir(workspace):
                    return self.verify_directory(workspace)
                # Fallback: try to iterate if it's a list of paths?
                # For now, if we can't extract a bundle, we might fail or use deliverable_text
                pass

        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        if not bundle:
            # Empty workspace
            return self._create_empty_report(source)

        return self.verify_bundle(bundle, source=source)

    def _create_empty_report(self, source: str) -> VerificationReport:
        gates = [
            GateResult(name='syntax', status=FAILED, method='ast.parse', detail='No Python files found'),
            GateResult(name='build', status=FAILED, method='packaging', detail='No packaging metadata found'),
            GateResult(name='smoke', status=FAILED, method='import', detail='No modules to import'),
            GateResult(name='tests', status=FAILED, method='pytest', detail='No test files found'),
            GateResult(name='telemetry', status=FAILED, method='ast', detail='No Python files to analyze'),
        ]
        return VerificationReport(
            gates=gates,
            score_penalty=len(gates) * self.penalty_per_gate,
            authored_files=0,
            python_files=0,
            source=source
        )

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        with tempfile.TemporaryDirectory() as tmpdir:
            # Write bundle to temp dir
            for path, content in bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmpdir, authored=bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Filter out excluded dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.relpath(os.path.join(root, d), workdir))]
                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        try:
                            with open(os.path.join(root, file), 'r', encoding='utf-8') as f:
                                authored[rel_path] = f.read()
                        except Exception:
                            pass

        # Filter bundle to ensure only authored files are considered
        filtered_authored = filter_bundle(authored)

        python_files = [p for p in filtered_authored.keys() if p.endswith('.py')]
        authored_count = len(filtered_authored)
        python_count = len(python_files)

        gates = []

        # 1. Syntax Gate
        gates.append(self._gate_syntax(workdir, python_files))

        # 2. Build Gate
        gates.append(self._gate_build(workdir, filtered_authored))

        # 3. Smoke Gate
        gates.append(self._gate_smoke(workdir, python_files))

        # 4. Tests Gate
        gates.append(self._gate_tests(workdir, python_files))

        # 5. Telemetry Gate
        gates.append(self._gate_telemetry(workdir, python_files))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_count,
            python_files=python_count,
            source=source
        )

    def _gate_syntax(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()
        if not python_files:
            return GateResult(name='syntax', status=FAILED, method='ast.parse', detail='No Python files found', duration_s=time.time()-start)

        errors = []
        for rel_path in python_files:
            full_path = os.path.join(workdir, rel_path)
            try:
                with open(full_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{rel_path}: {e}")
            except Exception as e:
                errors.append(f"{rel_path}: {e}")

        duration = time.time() - start
        if errors:
            return GateResult(name='syntax', status=FAILED, method='ast.parse', detail='; '.join(errors), duration_s=duration)
        return GateResult(name='syntax', status=PASSED, method='ast.parse', detail='All files parsed successfully', duration_s=duration)

    def _gate_build(self, workdir: str, bundle: Dict[str, str]) -> GateResult:
        start = time.time()

        # Check for packaging metadata
        has_pyproject = 'pyproject.toml' in bundle
        has_setup_py = 'setup.py' in bundle
        has_setup_cfg = 'setup.cfg' in bundle

        if not (has_pyproject or has_setup_py or has_setup_cfg):
            return GateResult(name='build', status=FAILED, method='packaging', detail='No packaging metadata found', duration_s=time.time()-start)

        # Validate pyproject.toml if present
        if has_pyproject:
            try:
                with open(os.path.join(workdir, 'pyproject.toml'), 'rb') as f:
                    data = tomllib.load(f)
                # Must contain at least one of [project], [build-system], or [tool]
                if not any(key in data for key in ['project', 'build-system', 'tool']):
                    return GateResult(name='build', status=FAILED, method='tomllib', detail='pyproject.toml missing required tables', duration_s=time.time()-start)
            except Exception as e:
                return GateResult(name='build', status=FAILED, method='tomllib', detail=f'Invalid pyproject.toml: {e}', duration_s=time.time()-start)

        # Try pip install
        try:
            # Check if pip is available
            subprocess.run([self.python_executable, '-m', 'pip', '--version'], check=True, capture_output=True, timeout=10)

            # Run pip install
            cmd = [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation']
            result = subprocess.run(cmd, cwd=workdir, capture_output=True, text=True, timeout=self.timeout_s)

            duration = time.time() - start
            if result.returncode == 0:
                return GateResult(name='build', status=PASSED, method='pip install', detail='Package installed successfully', duration_s=duration)
            else:
                return GateResult(name='build', status=FAILED, method='pip install', detail=f'pip install failed: {result.stderr}', duration_s=duration)
        except FileNotFoundError:
            return GateResult(name='build', status=SKIPPED, method='pip install', detail='pip not available', duration_s=time.time()-start)
        except subprocess.TimeoutExpired:
            return GateResult(name='build', status=FAILED, method='pip install', detail='pip install timed out', duration_s=time.time()-start)
        except Exception as e:
            return GateResult(name='build', status=FAILED, method='pip install', detail=f'Error running pip: {e}', duration_s=time.time()-start)

    def _gate_smoke(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()

        # Identify non-test modules
        # Exclude test files
        non_test_modules = []
        for rel_path in python_files:
            basename = os.path.basename(rel_path).lower()
            if 'test' in basename:
                continue
            # Convert path to module name
            # src/foo/bar.py -> foo.bar
            # foo/bar.py -> foo.bar
            # We need to handle src/ prefix if present

            # Determine module name relative to workdir or src/
            # The spec says: "Non-test authored modules must import in a subprocess with both workdir and os.path.join(workdir, "src") on PYTHONPATH."

            # Let's try to import the file directly by path or module name.
            # Using importlib is safer.
            non_test_modules.append(rel_path)

        if not non_test_modules:
            return GateResult(name='smoke', status=FAILED, method='import', detail='No importable modules found', duration_s=time.time()-start)

        # Construct PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        python_path = f"{workdir}:{src_dir}"
        if os.name == 'nt':
            python_path = f"{workdir};{src_dir}"

        env = os.environ.copy()
        env['PYTHONPATH'] = python_path

        # We'll try to import each module in a separate subprocess to isolate failures
        # Or one subprocess that tries all? 
        # Spec: "If no importable modules exist or any module fails with a syntax or runtime error, return FAILED."
        # "If module imports fail solely with ModuleNotFoundError for uninstalled third-party packages... return SKIPPED"

        # Let's run a script that imports all modules
        script = []
        for rel_path in non_test_modules:
            # Convert path to module name
            # Remove .py
            mod_path = rel_path[:-3] if rel_path.endswith('.py') else rel_path
            # Replace / with .
            mod_name = mod_path.replace('/', '.').replace('\\', '.')

            # Handle src/ prefix
            if mod_name.startswith('src.'):
                mod_name = mod_name[4:]

            # FIX: Use distinct variable names for exception handling to avoid UnboundLocalError
            # and ensure 'e' is not referenced outside the except block.
            script.append(f"try:\n    import {mod_name}\nexcept ModuleNotFoundError as mnf_err:\n    print(f'MODULE_NOT_FOUND:{mod_name}:{mnf_err}')\nexcept Exception as imp_err:\n    print(f'IMPORT_ERROR:{mod_name}:{imp_err}')\nelse:\n    print(f'OK:{mod_name}')")

        full_script = "\n".join(script)

        try:
            result = subprocess.run(
                [self.python_executable, '-c', full_script],
                cwd=workdir,
                env=env,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            duration = time.time() - start
            stdout = result.stdout
            stderr = result.stderr

            # Analyze output
            lines = stdout.strip().split('\n')
            has_import_error = False
            has_module_not_found = False
            has_success = False

            for line in lines:
                if line.startswith('IMPORT_ERROR:'):
                    has_import_error = True
                elif line.startswith('MODULE_NOT_FOUND:'):
                    has_module_not_found = True
                elif line.startswith('OK:'):
                    has_success = True

            if has_import_error:
                return GateResult(name='smoke', status=FAILED, method='import', detail='One or more modules failed to import due to runtime/syntax errors', duration_s=duration, evidence={'stdout': stdout, 'stderr': stderr})

            if not has_success and has_module_not_found:
                # All failures were ModuleNotFoundError
                return GateResult(name='smoke', status=SKIPPED, method='import', detail='Modules failed to import due to missing third-party packages', duration_s=duration, evidence={'stdout': stdout, 'stderr': stderr})

            if has_success:
                # Some succeeded, some might have failed with ModuleNotFoundError
                # If any succeeded, we consider it passed? 
                # Spec: "If no importable modules exist or any module fails with a syntax or runtime error, return FAILED."
                # It doesn't explicitly say what happens if some succeed and some fail with ModuleNotFoundError.
                # But "If module imports fail solely with ModuleNotFoundError... return SKIPPED".
                # If we have a mix, and no runtime errors, it's probably SKIPPED or PASSED?
                # Let's assume if we have successes, we passed the "importable" check, but if others failed with MNF, it's ambiguous.
                # However, usually if one module imports, the package structure is valid.
                # Let's return PASSED if at least one succeeded and no runtime errors.
                return GateResult(name='smoke', status=PASSED, method='import', detail='Modules imported successfully', duration_s=duration)

            # If we reach here, no successes and no import errors (only MNF)
            return GateResult(name='smoke', status=SKIPPED, method='import', detail='No modules could be imported due to missing dependencies', duration_s=duration)

        except subprocess.TimeoutExpired:
            return GateResult(name='smoke', status=FAILED, method='import', detail='Import check timed out', duration_s=time.time()-start)
        except Exception as e:
