                    if 'Ran 0 tests' in stdout or 'no tests ran' in stdout:
                        return GateResult(name='tests', status=SKIPPED, method='unittest', detail='Tests skipped due to missing dependencies', duration_s=duration)

                return GateResult(name='tests', status=FAILED, method='unittest', detail='Tests failed', duration_s=duration, evidence={'stdout': stdout, 'stderr': stderr})

        except subprocess.TimeoutExpired:
