DEFAULT_VERIFY_BUDGET = 3

@dataclass
class VerifyAttempt:
    """One verification call, recorded for the scorecard."""
    turn: int
    agent_role: str
    gate_status: Dict[str, str] = field(default_factory=dict)
    passed_count: int = 0
    evaluable_count: int = 0
    authored_files: int = 0

class VerificationLoop:
    """Runs the real execution harness against a live workspace, on request.

    Holds the per-firm verify budget and the attempt history, so a scorecard
    can report not just the final gate state but how many attempts it took --
    a firm that verifies once and passes is measurably different from one that
    needed three rounds.
    """

    _MAX_DETAIL_CHARS = 400
    _GATE_NAMES = ("syntax", "build", "smoke", "tests", "telemetry")

    def __init__(self, workspace: Any, budget: int = DEFAULT_VERIFY_BUDGET, timeout_s: int = 45):
        self.workspace = workspace
        self.budget = budget
        self.timeout_s = timeout_s
        self.used = 0
        self.attempts: List[VerifyAttempt] = []

        # Initialize the harness
        # The harness is expected to be compatible with the ExecutionHarness contract
        self.harness = ExecutionHarness(timeout_s=timeout_s)

    @property
    def remaining(self) -> int:
        return self.budget - self.used

    def verify(self, turn: int = 0, agent_role: str = '') -> str:
        """Runs every gate and returns an agent-readable report.

        The string is what lands in the agent's context, so it is terse by
        design.
        """
        # 1. Check Budget
        if self.remaining <= 0:
            return "BUDGET EXHAUSTED"

        # 2. Get Bundle
        try:
            raw_bundle = self.workspace.export_bundle()
        except Exception:
            raw_bundle = {}

        try:
            filtered_bundle = filter_bundle(raw_bundle)
        except Exception:
            filtered_bundle = {}

        file_count = len(filtered_bundle)

        # 3. Handle Empty Workspace
        if file_count == 0:
            self.used += 1
            return f"No files have been authored yet. Nothing to verify. ({self.remaining} verification attempt(s) remaining.)"

        # 4. Run Verification
        self.used += 1
        report = self.harness.verify_bundle(filtered_bundle)

        # Extract data from report
        gate_status = report.gate_status
        gate_detail = report.gate_detail

        # Calculate counts
        # evaluable_count counts gates whose status is not SKIPPED
        evaluable_count = sum(1 for status in gate_status.values() if status != SKIPPED)
        passed_count = sum(1 for status in gate_status.values() if status == PASSED)

        # Append Attempt
        attempt = VerifyAttempt(
            turn=turn,
            agent_role=agent_role,
            gate_status=gate_status,
            passed_count=passed_count,
            evaluable_count=evaluable_count,
            authored_files=file_count
        )
        self.attempts.append(attempt)

        # 5. Format Report
        lines = []

        # Header
        header = f"{passed_count}/{evaluable_count} evaluable gate(s) passing across {file_count} authored file(s)."
        lines.append(header)

        # Gate Details
        for name in self._GATE_NAMES:
            status = gate_status.get(name, SKIPPED)
            detail = gate_detail.get(name, "")

            # Map status to display string
            if status == PASSED:
                display_status = "PASS"
            elif status == FAILED:
                display_status = "FAIL"
            else:
                display_status = "SKIP"

            # Truncate detail
            if len(detail) > self._MAX_DETAIL_CHARS:
                detail = detail[:self._MAX_DETAIL_CHARS]

            line = f"  [{display_status}] {name}: {detail}"
            lines.append(line)

            # Special case for syntax failure
            if name == "syntax" and status == FAILED:
                lines.append("A file does not parse.")

        # Footer
        footer_skip = "SKIP means the gate could not be evaluated in this environment (usually an uninstalled third-party package). A skip is not a pass and earns no credit."
        footer_remaining = f"({self.remaining} verification attempt(s) remaining.)"

        lines.append(footer_skip)
        lines.append(footer_remaining)

        return "\n".join(lines)

    def summary(self) -> Dict[str, Any]:
        """Verification history for the scorecard."""
        best_passed_count = 0
        if self.attempts:
            best_passed_count = max(a.passed_count for a in self.attempts)

        final_gate_status = {}
        converged = False

        if self.attempts:
            final_attempt = self.attempts[-1]
            final_gate_status = final_attempt.gate_status
            # converged is bool(final and final.passed_count >= best_passed_count)
            # Note: 'final' in the spec likely refers to the final attempt object or its existence
            # The spec says: converged is bool(final and final.passed_count >= best_passed_count)
            # Interpreting 'final' as the last attempt in self.attempts
            if final_attempt.passed_count >= best_passed_count:
                converged = True
            else:
                converged = False
        else:
            converged = False

        attempts_list = []
        for a in self.attempts:
            attempts_list.append({
                "turn": a.turn,
                "agent_role": a.agent_role,
                "gate_status": a.gate_status,
                "passed": a.passed_count,
                "evaluable": a.evaluable_count,
                "authored_files": a.authored_files
            })

        return {
            "budget": self.budget,
            "used": self.used,
            "attempt_count": len(self.attempts),
            "best_passed_count": best_passed_count,
            "final_gate_status": final_gate_status,
            "converged": converged,
            "attempts": attempts_list
        }

