import ast
import sys
try:
    with open('hae/evaluation/verification_loop.py', 'r') as f:
        source = f.read()
except FileNotFoundError:
    print('MISSING_FILE')
    sys.exit(0)
tree = ast.parse(source)
found_unbound_e = False
for node in ast.walk(tree):
    if isinstance(node, ast.Try):
        for handler in node.handlers:
            if handler.name and handler.name.id == 'e':
                # Check if 'e' is used in the body
                for stmt in handler.body:
                    for subnode in ast.walk(stmt):
                        if isinstance(subnode, ast.Name) and subnode.id == 'e':
                            found_unbound_e = True
                            break
if found_unbound_e:
    print('FOUND_E_USAGE')
else:
    print('NO_E_USAGE')

