from hae.evaluation.harness import extract_code_blocks

def run_probe():
    text = '''
```python
def test_a(): pass
```
'''
    try:
        result = extract_code_blocks(text)
        print('EXTRACT_SUCCESS')
    except UnboundLocalError as e:
        print(f'EXTRACT_UNBOUND: {e}')
    except Exception as e:
        print(f'EXTRACT_ERROR: {e}')

